const _menuStyleStateSuffixes = {
  'BackgroundColor',
  'ShadowColor',
  'SurfaceTintColor',
  'Elevation',
  'Padding',
  'MinimumWidth',
  'MinimumHeight',
  'FixedWidth',
  'FixedHeight',
  'MaximumWidth',
  'MaximumHeight',
  'SideColor',
  'SideWidth',
  'SideStyle',
  'SideStrokeAlign',
  'ShapeKind',
  'ShapeRadiusTopLeft',
  'ShapeRadiusTopRight',
  'ShapeRadiusBottomRight',
  'ShapeRadiusBottomLeft',
  'ShapeCircleEccentricity',
  'MouseCursor',
};
const _menuStyleCommonFields = {
  'styleVisualDensityHorizontal',
  'styleVisualDensityVertical',
  'styleAlignmentKind',
  'styleAlignmentX',
  'styleAlignmentY',
};
bool _isMenuStyleLocal(String name) =>
    _menuStyleCommonFields.contains(name) ||
    _textButtonStatePrefixes.any(
      (prefix) =>
          name.startsWith(prefix) &&
          _menuStyleStateSuffixes.contains(name.substring(prefix.length)),
    );

Map<String, _PropertySpec> _menuAnchorProperties() => {
  for (final entry in _textButtonProperties().entries)
    if (_isMenuStyleLocal(entry.key)) entry.key: entry.value,
  for (final entry in {
    'controller': 'MenuController',
    'childFocusNode': 'FocusNode',
    'style': 'MenuStyle',
    'layerLink': 'LayerLink',
    'onOpen': 'VoidCallback',
    'onClose': 'VoidCallback',
    'onAnimationStatusChanged': 'ValueChanged<AnimationStatus>',
    'builder': 'MenuAnchorChildBuilder',
  }.entries)
    entry.key: _PropertySpec({
      'dartObjectReference',
      'null',
    }, dartObjectExpectedType: entry.value),
  'alignmentOffset': _PropertySpec({
    'offset',
    'dartObjectReference',
    'null',
  }, dartObjectExpectedType: 'Offset'),
  'reservedPadding': _PropertySpec(
    {'edgeInsets', 'edgeInsetsDirectional', 'dartObjectReference', 'null'},
    numericBounds: {
      'edgeInsets': _NumericBounds(),
      'edgeInsetsDirectional': _NumericBounds(),
    },
    dartObjectExpectedType: 'EdgeInsetsGeometry',
  ),
  for (final name in [
    'anchorTapClosesMenu',
    'consumeOutsideTap',
    'crossAxisUnconstrained',
    'useRootOverlay',
    'animated',
  ])
    name: _PropertySpec({'boolean'}),
  'clipBehavior': _PropertySpec(
    {'enum'},
    enumLibraryUri: _widgetsLibraryUri,
    enumType: 'Clip',
    enumValues: {'none', 'hardEdge', 'antiAlias', 'antiAliasWithSaveLayer'},
  ),
};

