Map<String, _PropertySpec> _radioListTileProperties() {
  final tile = _checkboxListTileProperties();
  final radio = _radioProperties();
  final properties = <String, _PropertySpec>{};
  for (final name in [
    'value',
    'groupValue',
    'onChanged',
    'mouseCursor',
    'toggleable',
    'activeColor',
    'fillColor',
    'hoverColor',
    'overlayColor',
    'splashRadius',
    'materialTapTargetSize',
    'isThreeLine',
    'dense',
    'selected',
    'controlAffinity',
    'autofocus',
    'contentPadding',
    'shape',
    'tileColor',
    'selectedTileColor',
    'visualDensity',
    'focusNode',
    'statesController',
    'onFocusChange',
    'enableFeedback',
    'horizontalTitleGap',
    'minVerticalPadding',
    'minLeadingWidth',
    'minTileHeight',
    'radioScaleFactor',
    'enabled',
    'titleAlignment',
    'internalAddSemanticForOnTap',
    'radioBackgroundColor',
    'radioSide',
    'radioInnerRadius',
    'useCupertinoCheckmarkStyle',
    'variant',
    'valueType',
    'nullableValueType',
  ]) {
    properties[name] = switch (name) {
      'value' ||
      'groupValue' ||
      'onChanged' ||
      'valueType' ||
      'nullableValueType' => radio[name]!,
      'radioScaleFactor' => tile['checkboxScaleFactor']!,
      'radioBackgroundColor' => radio['backgroundColor']!,
      'radioSide' => radio['side']!,
      'radioInnerRadius' => radio['innerRadius']!,
      _ => tile[name] ?? radio[name]!,
    };
  }
  for (final axis in ['Horizontal', 'Vertical']) {
    properties['visualDensity$axis'] = tile['visualDensity$axis']!;
  }
  for (final entry in _cardShapeProperties().entries) {
    if (entry.key != 'shape') properties[entry.key] = entry.value;
  }
  for (final family in ['fillColor', 'overlayColor', 'radioBackgroundColor']) {
    final source = family == 'radioBackgroundColor'
        ? 'backgroundColor'
        : family;
    for (final state in ['Default', ..._checkboxStateNames]) {
      properties['$family$state'] = radio['$source$state']!;
    }
  }
  for (final state in ['Default', ..._checkboxStateNames]) {
    properties['radioInnerRadius$state'] = radio['innerRadius$state']!;
  }
  for (final entry in radio.entries) {
    if (entry.key.startsWith('side') && entry.key != 'side') {
      properties['radioSide${entry.key.substring(4)}'] = entry.value;
    }
  }
  for (final state in ['Default', ..._checkboxStateNames]) {
    properties['mouseCursor$state'] = tile['mouseCursor$state']!;
  }
  _expect(
    properties.length == 153,
    'RadioListTile Canvas schema must contain 153 properties; got ${properties.length}.',
  );
  return properties;
}

