        {'string', 'null', 'dartObjectReference'},
        stringPattern: r'noop',
        dartObjectExpectedType: 'ImageErrorListener',
      ),
      'activeColor' ||
      'activeThumbColor' ||
      'activeTrackColor' ||
      'inactiveThumbColor' ||
      'inactiveTrackColor' ||
      'tileColor' ||
      'selectedTileColor' ||
      'hoverColor' => _canvasColorWithReference('Color'),
      _ => tile[name] ?? control[name]!,
    };
  }
  for (final axis in ['Horizontal', 'Vertical']) {
    properties['visualDensity$axis'] = tile['visualDensity$axis']!;
  }
  for (final entry in _cardShapeProperties().entries) {
    if (entry.key != 'shape') properties[entry.key] = entry.value;
