  for (final state in ['Default', ..._checkboxStateNames]) {
    properties.addAll(_switchIconProperties('thumbIcon$state'));
  }
  for (final state in ['Default', ..._checkboxStateNames]) {
    properties['mouseCursor$state'] = tile['mouseCursor$state']!;
  }
  _expect(
    properties.length == 236,
    'SwitchListTile Canvas schema must contain 236 properties; got ${properties.length}.',
