List<int> canvasPageSizes(String text) {
  if(text.trim().isEmpty)return [];
  final result=<int>[];
  for(final part in text.split(',')) {
    final token=part.trim();
    final value=int.tryParse(token);
    if(!RegExp(r'^[1-9][0-9]*$').hasMatch(token)||value==null||value>9007199254740991||result.contains(value)) {
      throw const FormatException('Page sizes must be distinct portable positive integers.');
    }
    result.add(value);
  }
  return result;
}

DateTime canvasGregorianDate(String text) {
  if(text.length!=10 || !RegExp(r'^[0-9]{4}-[0-9]{2}-[0-9]{2}$').hasMatch(text))throw const FormatException('Use Gregorian YYYY-MM-DD.');
  final parts=text.split('-').map(int.parse).toList(), date=DateTime(int.parse(text.substring(0,4)),int.parse(text.substring(5,7)),int.parse(text.substring(8,10)));
  if(parts[0]<1||parts[0]>9999||date.year!=parts[0]||date.month!=parts[1]||date.day!=parts[2])throw const FormatException('Invalid Gregorian date; local years are 0001–9999.');
  return date;
}
(DateTime,DateTime) canvasGregorianDateRange(String text) {
  if(text.length!=21||text[10]!='/')throw const FormatException('Use YYYY-MM-DD/YYYY-MM-DD.');
  final start=canvasGregorianDate(text.substring(0,10)),end=canvasGregorianDate(text.substring(11));
  if(start.isAfter(end))throw const FormatException('Start date must be on or before End date.');
  return (start,end);
}
