String canvasRuntimeWidgetSchemaContractForTesting() {
  final result = StringBuffer();
  final widgetTypes = _widgetSpecifications.keys.toList()..sort();
  for (final widgetType in widgetTypes) {
    final widget = _widgetSpecifications[widgetType]!;
    result.writeln('W|$widgetType');
    final propertyNames = widget.properties.keys.toList()..sort();
    for (final propertyName in propertyNames) {
      final property = widget.properties[propertyName]!;
      final kinds = property.kinds.toList()..sort();
      final numericEntries = property.numericBounds.entries.toList()
        ..sort((left, right) => left.key.compareTo(right.key));
      final numeric = numericEntries.isEmpty
          ? '-'
          : numericEntries
                .map(
                  (entry) =>
                      '${entry.key}:${_numericBoundsFingerprint(entry.value)}',
                )
                .join(';');
      final constraints = kinds
          .map(
            (kind) => '$kind:${_propertyConstraintFingerprint(property, kind)}',
          )
          .join(';');
      result
        ..write('P|$propertyName|${kinds.join(',')}|')
        ..write(property.required ? '1' : '0')
        ..write('|${property.creationDefaultFingerprint ?? '-'}|')
        ..write(numeric)
        ..writeln('|$constraints');
    }
    final slotNames = widget.slots.keys.toList()..sort();
    for (final slotName in slotNames) {
      final slot = widget.slots[slotName]!;
      result.writeln(
        'S|$slotName|${slot.cardinality}|${slot.required ? 1 : 0}|'
        '${slot.minimumChildren}|${slot.maximumChildren}|'
        '${slot.acceptance.fingerprint()}',
      );
    }
    if(widgetType==canvasDataColumnType)result.writeln('R|$widgetType|directParentSlot|flutter.material.DataTable,flutter.material.PaginatedDataTable|columns');
    if(canvasDataRowTypes.contains(widgetType))result.writeln('R|$widgetType|directParentSlot|flutter.material.DataTable|rows');
    if(canvasDataCellTypes.contains(widgetType)) {
      result.writeln('R|$widgetType|directParentSlot|flutter.material.DataRow|cells');
      result.writeln('R|$widgetType|directParentSlot|flutter.material.DataRow.byIndex|cells');
    }
    if(widgetType==canvasDataTableType)result.writeln('R|$widgetType|rectangularRows|nonemptyColumns|equalCellCount|boundedSortColumn|uniqueKnownRowKeys|exclusiveHeightBounds');
    if(widgetType==canvasDatePickerDialogType||widgetType==canvasCalendarDatePickerType)result.writeln('R|$widgetType|gregorianDates:v1:0001..9999|orderedInclusiveBounds|initialInRange|sourceCalendarOwnsRelations');
    if(widgetType==canvasDateRangePickerDialogType)result.writeln('R|$widgetType|gregorianDates:v1:0001..9999|range:v1:start/end|orderedInclusiveBounds|initialRangeInBounds|sourceCalendarOwnsRelations');
    if(widgetType==canvasPaginatedDataTableType)result.writeln('R|$widgetType|sourceOwnedRows|nonemptyColumns|boundedSortColumn|exclusiveHeightBounds|actionsRequireHeader|pageSizes|controllerPrimary');
    if(isCanvasDataTable(widgetType)||isCanvasDataDescriptor(widgetType))result.writeln('C|$widgetType|paletteCreate|dataTable.v1|2|2');
    if(widgetType=='flutter.widgets.TableRow') {
      result.writeln('R|$widgetType|directParentSlot|flutter.widgets.Table|children');
      result.writeln('C|$widgetType|paletteCreate|tableRow|2|48');
    }
    if(widgetType=='flutter.widgets.TableCell') result.writeln('R|$widgetType|directParentSlot|flutter.widgets.TableRow|children');
    if(widgetType=='flutter.widgets.Table') {
      result.writeln('R|$widgetType|rectangularRows|positiveEqualCellCount|uniqueRowAndCellKeys|baselineRequiresTextBaseline');
      result.writeln('R|$widgetType|columnWidths|tableColumnWidths.v1|depth8|nodes256|index9999');
      result.writeln('C|$widgetType|paletteCreate|tableGrid|2|2|48');
    }
    if (widget.traits.contains(_sliverWidgetTrait)) {
      result.writeln('R|$widgetType|requiresSlotTrait|flutter.widgets.Sliver');
    }
    if (widgetType == 'flutter.widgets.SliverCrossAxisExpanded') {
      result.writeln('R|$widgetType|directParentSlot|flutter.widgets.SliverCrossAxisGroup|slivers');
    }
    if (isCanvasStackPositionedWidgetType(widgetType)) {
      result.writeln('R|$widgetType|directParentSlot|flutter.widgets.Stack|children');
    }
    if (_isFlexRestrictedWidgetType(widgetType)) {
      result
        ..writeln(
          'R|$widgetType|directParentSlot|'
          'flutter.widgets.Column|children',
        )
        ..writeln(
          'R|$widgetType|directParentSlot|'
          'flutter.widgets.Row|children',
        );
      result.writeln('R|$widgetType|directParentSlot|flutter.material.DataColumn|label');
      if (_isFlexParentDataWidgetType(widgetType)) {
        result.writeln('C|$widgetType|paletteCreate|wrapExistingChild|child');
      }
    } else if (widgetType == 'flutter.widgets.AnimatedCrossFade') {
      result.writeln('C|$widgetType|paletteCreate|seedBoxChildren|firstChild|48|48|secondChild|48|80');
    } else if (widgetType == 'flutter.widgets.LayoutId') {
      result.writeln('R|$widgetType|directParentSlot|flutter.widgets.CustomMultiChildLayout|children');
      result.writeln('C|$widgetType|paletteCreate|seedBoxChild|child|48');
      result.writeln('C|$widgetType|paletteCreate|stableNodeId|id');
    } else if (widgetType == 'flutter.widgets.SliverFloatingHeader') {
      result.writeln('C|$widgetType|paletteCreate|seedBoxChild|child|48');
    } else if (isCanvasReviewedRequiredChildWrapperWidgetType(widgetType)) {
      result.writeln(
        'C|$widgetType|paletteCreate|wrapExistingChild|'
        '${canvasReviewedRequiredWrapperSlot(widgetType)}',
      );
    }
  }
  return result.toString();
}

bool _placementAccepts(
  String parentWidgetType,
  String slotName,
  String childWidgetType,
) {
  if(!canvasDataDescriptorPlacement(childWidgetType,parentWidgetType,slotName))return false;
  if (childWidgetType == 'flutter.widgets.TableRow') return parentWidgetType=='flutter.widgets.Table' && slotName=='children';
  if (childWidgetType == 'flutter.widgets.TableCell') return parentWidgetType=='flutter.widgets.TableRow' && slotName=='children';
  if (childWidgetType == 'flutter.widgets.LayoutId') {
    return parentWidgetType == 'flutter.widgets.CustomMultiChildLayout' && slotName == 'children';
  }
  if (childWidgetType == 'flutter.widgets.SliverCrossAxisExpanded') {
    return parentWidgetType == 'flutter.widgets.SliverCrossAxisGroup' && slotName == 'slivers';
  }
  if (isCanvasStackPositionedWidgetType(childWidgetType)) {
    return parentWidgetType == 'flutter.widgets.Stack' && slotName == 'children';
  }
  if (!_isFlexRestrictedWidgetType(childWidgetType)) {
    return true;
  }
  return slotName == 'label'&&parentWidgetType==canvasDataColumnType || slotName == 'children' &&
      (parentWidgetType == 'flutter.widgets.Row' ||
          parentWidgetType == 'flutter.widgets.Column');
}

bool isCanvasStackPositionedWidgetType(String type) =>
    type == 'flutter.widgets.PositionedTransition' ||
    type == 'flutter.widgets.RelativePositionedTransition' ||
    type == 'flutter.widgets.AnimatedPositioned' ||
    type == 'flutter.widgets.AnimatedPositioned.fromRect' ||
    type == 'flutter.widgets.AnimatedPositionedDirectional';

bool _isFlexParentDataWidgetType(String widgetType) =>
    widgetType == 'flutter.widgets.Expanded' ||
    widgetType == 'flutter.widgets.Flexible';

/// Whether the reviewed schema can be created atomically by wrapping an
/// existing child without inventing any persisted constructor value.
bool isCanvasReviewedRequiredChildWrapperWidgetType(String widgetType) {
  return canvasReviewedRequiredWrapperSlot(widgetType) != null;
}

/// The reviewed required AnyWidget or Sliver slot used by atomic palette wrapping.
/// IconButton wraps into `icon`; existing wrappers continue to use `child`.
String? canvasReviewedRequiredWrapperSlot(String widgetType) {
  if (isCanvasDataDescriptor(widgetType) || widgetType == 'flutter.widgets.SliverFloatingHeader' || widgetType == 'flutter.widgets.LayoutId') return null;
  final specification = _widgetSpecifications[widgetType];
  if (specification == null) {
    return null;
  }
  final requiredSlots = specification.slots.entries
      .where(
        (entry) => entry.value.required && entry.value.minimumChildren == 1,
      )
      .toList(growable: false);
  if (requiredSlots.length != 1) return null;
  final slotName = requiredSlots.single.key;
  final child = requiredSlots.single.value;
  if (child.cardinality != 'single' ||
      !child.required ||
      child.minimumChildren != 1 ||
      child.maximumChildren != 1 ||
      !(child.acceptance.kind == _SlotAcceptanceKind.any ||
        child.acceptance.kind == _SlotAcceptanceKind.requiredTrait &&
          child.acceptance.requiredTrait == _sliverWidgetTrait)) {
    return null;
  }
  if (specification.slots.entries.any(
    (entry) =>
        entry.key != slotName &&
        (entry.value.required || entry.value.minimumChildren != 0),
  )) {
    return null;
  }
  return specification.properties.values.every(
        (property) =>
            !property.required || property.creationDefaultFingerprint != null,
      )
      ? slotName
      : null;
}

bool _isFlexRestrictedWidgetType(String widgetType) =>
    _isFlexParentDataWidgetType(widgetType) ||
    widgetType == 'flutter.widgets.Spacer';

bool isCanvasReviewedWidgetType(String widgetType) =>
    _widgetSpecifications.containsKey(widgetType);

Set<String> canvasWidgetTraitsForType(String widgetType) =>
    _widgetSpecifications[widgetType]?.traits ?? const {};

String _propertyConstraintFingerprint(_PropertySpec spec, String kind) {
  final numeric = spec.numericBounds[kind];
  if (kind == 'iconData') {
    return spec.materialIconsOnly
        ? _canvasMaterialIconConstraintFingerprint
        : _canvasIconDataConstraintFingerprint;
  }
  if (kind == 'edgeInsets' || kind == 'edgeInsetsDirectional') {
    _expect(numeric != null, 'Canvas EdgeInsets schema is incomplete.');
    final contractKind = spec.kinds.contains('edgeInsetsDirectional')
        ? 'edgeInsets'
        : 'edgeInsetsPhysical';
    return '$contractKind:${spec.edgeInsetsNonNegative ? 1 : 0}:'
        '${_numericBoundsFingerprint(numeric!)}';
  }
  if (numeric != null) {
    return 'range:${_numericBoundsFingerprint(numeric)}';
  }
  if (kind == 'enum') {
    final library = spec.enumLibraryUri;
    final type = spec.enumType;
    _expect(
      library != null && type != null && spec.enumValues.isNotEmpty,
      'Canvas enum schema is incomplete.',
    );
    final values = spec.enumValues.toList()..sort();
    return 'enum:${_base64Fingerprint(library!)}:$type:${values.join(',')}';
  }
  if (kind == 'string') {
    if (spec.stringPattern case final pattern?) {
      return 'pattern:${_base64Fingerprint(pattern)}';
    }
    if (spec.explicitStringLength) {
      return 'length:${spec.minimumStringLength}:${spec.maximumStringLength}';
    }
    return 'any';
  }
  if (kind == 'themeToken') {
    final tokens = spec.themeTokens.toList()..sort();
    _expect(tokens.isNotEmpty, 'Canvas theme-token schema is empty.');
    return 'tokens:${tokens.join(',')}';
  }
  if (kind == 'paint') {
    final tokens = canvasColorSchemeThemeTokens.toList()..sort();
    return 'paintTokens:${tokens.join(',')}';
  }
  if (kind == 'shadowList') {
    final tokens = canvasColorSchemeThemeTokens.toList()..sort();
    return 'shadowTokens:${tokens.join(',')}';
  }
  if (kind == 'fontVariationList') {
    return 'fontVariationList';
  }
  if (kind == 'boxConstraints') {
    return 'boxConstraints:v2:finiteOrPositiveInfinity';
  }
  if (kind == 'size') {
    return 'size:finiteNonNegative';
  }
  if (kind == 'alignmentGeometry') {
    return spec.alignmentPhysicalOnly ? 'alignment:physical' : kind;
  }
  if (kind == 'matrix4') {
    return kind;
  }
  if (kind == 'offset') {
    return 'offset:finiteSigned';
  }
  if (kind == 'imageProvider') {
    return 'imageProvider:v1:asset,exactAsset:package:exactScale:'
        'resize(1..16384,exact,fit,allowUpscaling)';
  }
  if (kind == 'gradient') {
    final tokens = spec.themeTokens.toList()..sort();
    _expect(tokens.isNotEmpty, 'Canvas gradient token schema is empty.');
    return 'gradient:v1:linear,radial,sweep:stops(2..256,ordered,0..1):'
        'alignment(physical,directional):tile(clamp,repeated,mirror,decal):'
        'rotation:finite:theme=${tokens.join(',')}';
  }
  if (kind == 'boxDecoration') {
    final tokens = spec.themeTokens.toList()..sort();
    _expect(tokens.isNotEmpty, 'Canvas BoxDecoration token schema is empty.');
    return 'boxDecoration:v2:'
        'imageProvider:v1:asset,exactAsset:package:exactScale:'
        'resize(1..16384,exact,fit,allowUpscaling):decorationImage:v1:'
        'onError,colorFilter(mode,matrix20,linearToSrgbGamma,'
        'srgbToLinearGamma,saturation),fit,alignment,centerSlice,repeat,'
        'matchTextDirection,scale,opacity,filterQuality,invertColors,'
        'isAntiAlias:centerSliceFit(except:cover,none):theme='
        '${tokens.join(',')}';
  }
  if (kind == 'borderRadius') {
    return spec.borderRadiusPhysicalOnly
        ? 'borderRadius:v1:physical:finiteNonNegative'
        : 'borderRadius:v1:physical,directional:finiteNonNegative';
  }
  if (kind == 'shapeBorderClipper') {
    return 'shapeBorderClipper:v1:roundedRectangle,beveledRectangle,'
        'continuousRectangle,roundedSuperellipse,circle,stadium:'
        'finiteNonNegativeRadius:explicitDirectional:ltr,rtl';
  }
  if (kind == 'dartObjectReference') {
    final expectedType = spec.dartObjectExpectedType;
    _expect(
      expectedType != null && expectedType.isNotEmpty,
      'Canvas Dart-object-reference schema is missing its expected type.',
    );
    return 'dartObjectReference:v1:$expectedType:'
        'currentOrPackage:root,optionalMember:reference,'
        'zeroArgumentInvocation:requiredConstnessBoolean(false,true)';
  }
  if (kind == 'callback') {
    return 'callbackReference';
  }
  return 'any';
}

String _numericBoundsFingerprint(_NumericBounds bounds) =>
    '${_canonicalBound(bounds.minimum)}:${bounds.minimumInclusive ? 1 : 0}:'
    '${_canonicalBound(bounds.maximum)}:${bounds.maximumInclusive ? 1 : 0}';

String _canonicalBound(num? value) {
  if (value == null) {
    return '*';
  }
  if (value == 0) {
    return '0';
  }
  return value.toString();
}

String _base64Fingerprint(String value) =>
    base64Url.encode(utf8.encode(value)).replaceAll('=', '');

class _NodeBudget {
  int count = 0;
  final ids = <String>{};
  final imageResourceIds = <String>{};
  final semanticsIdentifierPaths = <String, String>{};
}

void _validatePropertyRelationships(
  String type,
  Map<String, CanvasValue> properties,
  String path,
  _NodeBudget budget,
) {
  if (type == 'flutter.widgets.CustomPaint') {
    final hasPainter = ['painter', 'foregroundPainter'].any((name) => properties[name]?.kind == 'dartObjectReferencePresence');
    final hint = ['isComplex', 'willChange'].any((name) => properties[name]?.value == true);
    _expect(hasPainter || !hint, 'Canvas CustomPaint cache hints require Painter or Foreground painter: $path/properties/isComplex');
  }
  if (type == 'flutter.widgets.BackdropFilter' || type == 'flutter.widgets.BackdropFilter.grouped') {
    final config = properties['filterConfig'];
    final needsFilter = config == null || config.kind == 'null' || config.value == 'wrap';
    final filter = properties['filter'];
    _expect(!needsFilter || filter != null && filter.kind != 'null',
        'Canvas BackdropFilter requires Filter or Filter config; config wrap requires Filter: $path/properties/filter');
    _expect(!needsFilter || filter?.value != 'shader' || properties['shader']?.kind == 'dartObjectReferencePresence',
        'Canvas BackdropFilter shader requires a FragmentShader source: $path/properties/shader');
  }
  if (type == 'flutter.widgets.ImageFiltered' && properties['imageFilter']?.value == 'shader') {
    _expect(properties['shader']?.kind == 'dartObjectReferencePresence',
        'Canvas ImageFiltered shader requires a FragmentShader source: $path/properties/shader');
  }
  if (type == 'flutter.widgets.SizeTransition') {
    bool nonNull(String name) => properties.containsKey(name) && properties[name]!.kind != 'null';
    _expect(!nonNull('axisAlignment') || !nonNull('alignment'),
      'Canvas SizeTransition alignment and deprecated axisAlignment cannot both be non-null; reset one or use explicit null: $path/properties/alignment');
    return;
  }
  if (type == 'flutter.material.Tooltip' ||
      type == 'flutter.material.TooltipTheme') {
    bool nonNull(String name) =>
        properties.containsKey(name) && properties[name]!.kind != 'null';
    if (type == 'flutter.material.Tooltip') {
      _expect(
        nonNull('message') != nonNull('richMessage'),
        'Canvas Tooltip requires exactly one nonnull message or richMessage: $path/properties',
      );
    } else {
      _expect(
        !properties.containsKey('data') || properties.length == 1,
        'Canvas TooltipTheme whole data and local fields are mutually exclusive: $path/properties',
      );
    }
    _expect(
      !nonNull('height') || !nonNull('constraints'),
      'Canvas Tooltip nonnull height and constraints are mutually exclusive: $path/properties',
    );
    _expect(
      !properties.containsKey('textStyle') ||
          !properties.keys.any(
            (name) => name.startsWith('textStyle') && name != 'textStyle',
          ),
      'Canvas Tooltip whole textStyle and local fields are mutually exclusive: $path/properties',
    );
    _validateAppBarTextStyleRelationships(
      properties,
      path: path,
      prefix: 'textStyle',
      widgetName: 'Tooltip',
    );
    return;
  }
  if (type == 'flutter.widgets.SliverFloatingHeader') {
    _expect(!properties.containsKey('animationStyle') ||
        !properties.keys.any((name) => name.startsWith('animationStyle') && name != 'animationStyle'),
        'Canvas SliverFloatingHeader whole AnimationStyle and local fields are mutually exclusive: $path/properties');
    return;
  }
  if (type == 'flutter.material.ExpansionTile') {
    for (final family in ['shape', 'collapsedShape']) {
      _validateCardRelationships(
        properties,
        path,
        widgetName: 'ExpansionTile',
        prefix: family,
      );
    }
    _expect(
      !properties.containsKey('visualDensity') ||
          (!properties.containsKey('visualDensityHorizontal') &&
              !properties.containsKey('visualDensityVertical')),
      'Canvas ExpansionTile whole visualDensity and local axes are mutually exclusive: $path/properties',
    );
    _expect(
      !properties.containsKey('expansionAnimationStyle') ||
          !properties.keys.any(
            (name) =>
                name.startsWith('expansionAnimationStyle') &&
                name != 'expansionAnimationStyle',
          ),
      'Canvas ExpansionTile whole expansionAnimationStyle and local fields are mutually exclusive: $path/properties',
    );
    return;
  }
  if (type == 'flutter.material.CheckboxListTile') {
    _expect(
      properties['value']?.kind != 'null' ||
          properties['tristate']?.value == true,
      'Canvas CheckboxListTile null value requires tristate true: $path/properties/value',
    );
    _validateCardRelationships(
      properties,
      path,
      widgetName: 'CheckboxListTile',
    );
    _validateCardRelationships(
      properties,
      path,
      widgetName: 'CheckboxListTile.checkboxShape',
      prefix: 'checkboxShape',
    );
    _expect(
      !properties.containsKey('visualDensity') ||
          (!properties.containsKey('visualDensityHorizontal') &&
              !properties.containsKey('visualDensityVertical')),
      'Canvas CheckboxListTile visualDensity reference and local axes are mutually exclusive: $path/properties',
    );
    for (final family in ['fillColor', 'overlayColor', 'mouseCursor']) {
      final local = [
        'Default',
        ..._checkboxStateNames,
      ].any((state) => properties.containsKey('$family$state'));
      _expect(
        !local || !properties.containsKey(family),
        'Canvas CheckboxListTile $family reference and local states are mutually exclusive: $path/properties/$family',
      );
      _expect(
        !local || properties.containsKey('${family}Default'),
        'Canvas CheckboxListTile local $family requires Default: $path/properties/${family}Default',
      );
    }
    final localSide = properties.keys.where(
      (name) => name.startsWith('side') && name != 'side',
    );
    _expect(
      !properties.containsKey('side') || localSide.isEmpty,
      'Canvas CheckboxListTile side reference and local side fields are mutually exclusive: $path/properties/side',
    );
    for (final state in _checkboxStateNames) {
      final prefix = 'side$state';
      final details = [
        'Color',
        'Width',
        'Style',
        'StrokeAlign',
      ].any((suffix) => properties.containsKey('$prefix$suffix'));
      final mode = properties['${prefix}Mode']?.value;
      _expect(
        (mode == null && !details) || properties['sideStateful']?.value == true,
        'Canvas CheckboxListTile state side requires sideStateful true: $path/properties/$prefix',
      );
      _expect(
        mode != 'inherit' || !details,
        'Canvas CheckboxListTile inherit side mode excludes details: $path/properties/$prefix',
      );
    }
    return;
  }
  if (type == 'flutter.material.ListTile') {
    _validateCardRelationships(properties, path, widgetName: 'ListTile');
    _expect(
      !properties.containsKey('visualDensity') ||
          (!properties.containsKey('visualDensityHorizontal') &&
              !properties.containsKey('visualDensityVertical')),
      'Canvas ListTile visualDensity reference and local axes are mutually exclusive: $path/properties',
    );
    for (final family in [
      'titleTextStyle',
      'subtitleTextStyle',
      'leadingAndTrailingTextStyle',
    ]) {
      _expect(
        !properties.containsKey(family) ||
            !properties.keys.any(
              (name) => name.startsWith(family) && name != family,
            ),
        'Canvas ListTile $family reference and local fields are mutually exclusive: $path/properties/$family',
      );
      _validateAppBarTextStyleRelationships(
        properties,
        prefix: family,
        path: path,
        widgetName: 'ListTile',
      );
    }
    for (final family in ['iconColor', 'textColor', 'mouseCursor']) {
      final local = [
        'Default',
        ..._checkboxStateNames,
      ].any((state) => properties.containsKey('$family$state'));
      _expect(
        !local || !properties.containsKey(family),
        'Canvas ListTile $family value and local states are mutually exclusive: $path/properties/$family',
      );
      _expect(
        !local || properties.containsKey('${family}Default'),
        'Canvas ListTile local $family requires Default: $path/properties/${family}Default',
      );
    }
    return;
  }
  if (type == 'flutter.material.Checkbox') {
    _expect(
      properties['value']?.kind != 'null' ||
          properties['tristate']?.value == true,
      'Canvas Checkbox null value requires tristate true: $path/properties/value',
    );
    _validateCardRelationships(properties, path, widgetName: 'Checkbox');
    for (final family in ['fillColor', 'overlayColor']) {
      _expect(
        !properties.containsKey(family) ||
            ![
              'Default',
              ..._checkboxStateNames,
            ].any((state) => properties.containsKey('$family$state')),
        'Canvas Checkbox $family reference and local state colors are mutually exclusive: $path/properties/$family',
      );
    }
    final localSide = properties.keys.where(
      (name) => name.startsWith('side') && name != 'side',
    );
    _expect(
      !properties.containsKey('side') || localSide.isEmpty,
      'Canvas Checkbox side reference and local side fields are mutually exclusive: $path/properties/side',
    );
    for (final state in _checkboxStateNames) {
      final prefix = 'side$state';
      final details = [
        'Color',
        'Width',
        'Style',
        'StrokeAlign',
      ].any((suffix) => properties.containsKey('$prefix$suffix'));
      final mode = properties['${prefix}Mode']?.value;
      _expect(
        (mode == null && !details) || properties['sideStateful']?.value == true,
        'Canvas Checkbox state side requires sideStateful true: $path/properties/$prefix',
      );
      _expect(
        mode != 'inherit' || !details,
        'Canvas Checkbox inherit side mode excludes details: $path/properties/$prefix',
      );
    }
    return;
  }
  if (type == 'flutter.widgets.ValueListenableBuilder' ||
      type == 'flutter.widgets.ValueListenableBuilder.sliver') {
    _expect(
      properties['valueType']?.kind != 'dartObjectReferencePresence' ||
          properties['nullableValueType']?.value == true ||
          properties['valueListenable']?.kind == 'dartObjectReferencePresence',
      'Canvas ValueListenableBuilder non-nullable project type requires a source reference: $path/properties/valueListenable',
    );
    return;
  }
  if (type == 'flutter.widgets.TweenAnimationBuilder' ||
      type == 'flutter.widgets.TweenAnimationBuilder.sliver') {
    _expect(
      properties['valueType']?.kind != 'dartObjectReferencePresence' ||
          properties['tween']?.kind == 'dartObjectReferencePresence',
      'Canvas TweenAnimationBuilder project type requires a Tween with non-null end: $path/properties/tween',
    );
    return;
  }
  if (type == 'flutter.material.Radio' ||
      type == 'flutter.material.RadioListTile' ||
      type == 'flutter.widgets.RadioGroup') {
    _expect(
      properties['value']?.kind != 'null' ||
          properties['nullableValueType']?.value == true,
      'Canvas Radio null value requires nullableValueType true: $path/properties/value',
    );
    final valueType = properties['valueType']?.kind == 'string'
        ? properties['valueType']!.value as String
        : null;
    for (final name in ['value', 'groupValue']) {
      final kind = properties[name]?.kind;
      if (kind == null ||
          kind == 'null' ||
          kind == 'dartObjectReferencePresence' ||
          valueType == null) {
        continue;
      }
      final allowed = switch (valueType) {
        'String' => {'string'},
        'int' => {'integer'},
        'double' || 'num' => {'integer', 'double', 'enum'},
        'bool' => {'boolean'},
        _ => {'string', 'integer', 'double', 'enum', 'boolean'},
      };
      _expect(
        allowed.contains(kind),
        'Canvas $type $name must match valueType: $path/properties/$name',
      );
    }
    if (type == 'flutter.widgets.RadioGroup') return;
    final tile = type == 'flutter.material.RadioListTile';
    _expect(
      tile ||
          properties['variant']?.value == 'adaptive' ||
          !properties.containsKey('useCupertinoCheckmarkStyle'),
      'Canvas Radio useCupertinoCheckmarkStyle requires adaptive: $path/properties',
    );
    _expect(
      !properties.containsKey('visualDensity') ||
          (!properties.containsKey('visualDensityHorizontal') &&
              !properties.containsKey('visualDensityVertical')),
      'Canvas Radio visualDensity reference and local axes are mutually exclusive: $path/properties',
    );
    for (final family in [
      'fillColor',
      'overlayColor',
      if (tile) 'radioBackgroundColor' else 'backgroundColor',
      if (tile) 'radioInnerRadius' else 'innerRadius',
    ]) {
      _expect(
        !properties.containsKey(family) ||
            ![
              'Default',
              ..._checkboxStateNames,
            ].any((state) => properties.containsKey('$family$state')),
        'Canvas Radio $family reference and local states are mutually exclusive: $path/properties/$family',
      );
    }
    final side = tile ? 'radioSide' : 'side';
    _expect(
      !properties.containsKey(side) ||
          !properties.keys.any((name) => name != side && name.startsWith(side)),
      'Canvas Radio side reference and local fields are mutually exclusive: $path/properties/side',
    );
    for (final state in _checkboxStateNames) {
      final prefix = '$side$state';
      final details = [
        'Color',
        'Width',
        'Style',
        'StrokeAlign',
      ].any((suffix) => properties.containsKey('$prefix$suffix'));
      final mode = properties['${prefix}Mode']?.value;
      _expect(
        (mode == null && !details) ||
            properties['${side}Stateful']?.value == true,
        'Canvas Radio state side requires sideStateful true: $path/properties/$prefix',
      );
      _expect(
        mode != 'inherit' || !details,
        'Canvas Radio inherit side mode excludes details: $path/properties/$prefix',
      );
    }
    if (tile) {
      _validateCardRelationships(properties, path, widgetName: 'RadioListTile');
      final cursors = [
        'Default',
        ..._checkboxStateNames,
      ].any((state) => properties.containsKey('mouseCursor$state'));
      _expect(
        !cursors || !properties.containsKey('mouseCursor'),
        'Canvas RadioListTile cursor reference and local states are mutually exclusive: $path/properties/mouseCursor',
      );
      _expect(
        !cursors || properties.containsKey('mouseCursorDefault'),
        'Canvas RadioListTile local cursor requires Default: $path/properties/mouseCursorDefault',
      );
    }
    return;
  }
  if (type == 'flutter.material.RangeSlider') {
    double? number(String name) => switch (properties[name]?.value) {
      CanvasEnumValue(value: 'infinity') => double.infinity,
      CanvasEnumValue(value: 'negativeInfinity') => double.negativeInfinity,
      num value => value.toDouble(),
      _ => null,
    };
    final min = number('min') ?? 0;
    final max = number('max') ?? 1;
    final start = number('valuesStart')!;
    final end = number('valuesEnd')!;
    _expect(
      min <= max,
      'Canvas RangeSlider min must not exceed max: $path/properties',
    );
    _expect(
      start <= end,
      'Canvas RangeSlider valuesStart must not exceed valuesEnd: $path/properties',
    );
    _expect(
      start >= min && end <= max,
      'Canvas RangeSlider values must be within min/max: $path/properties',
    );
    _expect(
      !properties.containsKey('labels') ||
          (!properties.containsKey('labelsStart') &&
              !properties.containsKey('labelsEnd')),
      'Canvas RangeSlider labels and local labels are mutually exclusive: $path/properties/labels',
    );
    for (final family in ['overlayColor', 'mouseCursor']) {
      _expect(
        !properties.containsKey(family) ||
            ![
              'Default',
              ..._checkboxStateNames,
            ].any((state) => properties.containsKey('$family$state')),
        'Canvas RangeSlider $family reference and local states are mutually exclusive: $path/properties/$family',
      );
    }
    return;
  }
  if (type == 'flutter.material.Slider') {
    double? number(String name) => switch (properties[name]?.value) {
      CanvasEnumValue(value: 'infinity') => double.infinity,
      CanvasEnumValue(value: 'negativeInfinity') => double.negativeInfinity,
      num value => value.toDouble(),
      _ => null,
    };
    final min = number('min') ?? 0;
    final max = number('max') ?? 1;
    final value = number('value')!;
    final secondary = number('secondaryTrackValue');
    _expect(
      min <= max,
      'Canvas Slider min must not exceed max: $path/properties',
    );
    _expect(
      value >= min && value <= max,
      'Canvas Slider value must be within min/max: $path/properties/value',
    );
    _expect(
      secondary == null || (secondary >= min && secondary <= max),
      'Canvas Slider secondaryTrackValue must be within min/max: $path/properties/secondaryTrackValue',
    );
    _expect(
      properties['variant']?.value != 'adaptive' ||
          !properties.containsKey('padding'),
      'Canvas Slider.adaptive has no padding argument: $path/properties/padding',
    );
    _expect(
      !properties.containsKey('overlayColor') ||
          ![
            'Default',
            ..._checkboxStateNames,
          ].any((state) => properties.containsKey('overlayColor$state')),
      'Canvas Slider overlayColor reference and local state colors are mutually exclusive: $path/properties/overlayColor',
    );
    return;
  }
  if (type == 'flutter.material.Switch' ||
      type == 'flutter.material.SwitchListTile') {
    final tile = type == 'flutter.material.SwitchListTile';
    _expect(
      tile ||
          properties['variant']?.value == 'adaptive' ||
          !properties.containsKey('applyCupertinoTheme'),
      'Canvas Switch.applyCupertinoTheme requires adaptive: $path/properties/applyCupertinoTheme',
    );
    for (final entry in const {
      'onActiveThumbImageError': 'activeThumbImage',
      'onInactiveThumbImageError': 'inactiveThumbImage',
    }.entries) {
      _expect(
        !properties.containsKey(entry.key) ||
            properties[entry.key]?.kind == 'null' ||
            properties.containsKey(entry.value),
        'Canvas Switch ${entry.key} requires ${entry.value}: $path/properties/${entry.key}',
      );
    }
    for (final family in [
      'thumbColor',
      'trackColor',
      'trackOutlineColor',
      'overlayColor',
      'trackOutlineWidth',
      'thumbIcon',
    ]) {
      _expect(
        !properties.containsKey(family) ||
            !properties.keys.any(
              (name) => name != family && name.startsWith(family),
            ),
        'Canvas Switch $family reference and local fields are mutually exclusive: $path/properties/$family',
      );
    }
    for (final state in ['Default', ..._checkboxStateNames]) {
      final prefix = 'thumbIcon$state';
      _expect(
        properties['${prefix}Mode']?.value != 'inherit' ||
            !_switchIconSuffixes.any(
              (suffix) => properties.containsKey('$prefix$suffix'),
            ),
        'Canvas Switch thumb icon inherit excludes Icon fields: $path/properties/$prefix',
      );
    }
    if (tile) {
      _validateCardRelationships(
        properties,
        path,
        widgetName: 'SwitchListTile',
      );
      _expect(
        !properties.containsKey('visualDensity') ||
            (!properties.containsKey('visualDensityHorizontal') &&
                !properties.containsKey('visualDensityVertical')),
        'Canvas SwitchListTile visualDensity reference and local axes are mutually exclusive: $path/properties',
      );
      final cursors = [
        'Default',
        ..._checkboxStateNames,
      ].any((state) => properties.containsKey('mouseCursor$state'));
      _expect(
        !cursors || !properties.containsKey('mouseCursor'),
        'Canvas SwitchListTile cursor reference and local states are mutually exclusive: $path/properties/mouseCursor',
      );
      _expect(
        !cursors || properties.containsKey('mouseCursorDefault'),
        'Canvas SwitchListTile local cursor requires Default: $path/properties/mouseCursorDefault',
      );
    }
    return;
  }
  if (type == 'flutter.material.RefreshIndicator') {
    if (properties['variant']?.value == 'noSpinner') {
      for (final name in const [
        'displacement',
        'edgeOffset',
        'color',
        'backgroundColor',
        'strokeWidth',
      ]) {
        _expect(
          !properties.containsKey(name),
          'Canvas RefreshIndicator.noSpinner has no $name argument: $path/properties/$name',
        );
      }
    } else {
      _expect(
        !properties.containsKey('onStatusChange'),
        'Canvas RefreshIndicator.onStatusChange requires noSpinner: $path/properties/onStatusChange',
      );
    }
    return;
  }
  if (type == 'flutter.material.CircularProgressIndicator') {
    _expect(
      properties['variant']?.value != 'adaptive' ||
          !properties.containsKey('color'),
      'Canvas CircularProgressIndicator.adaptive has no color argument: $path/properties/color',
    );
    _expect(
      !properties.containsKey('value') || !properties.containsKey('controller'),
      'Canvas CircularProgressIndicator value and controller are mutually exclusive: $path/properties',
    );
    return;
  }
  if (type == 'flutter.material.LinearProgressIndicator') {
    _expect(
      !properties.containsKey('value') || !properties.containsKey('controller'),
      'Canvas LinearProgressIndicator value and controller are mutually exclusive: $path/properties',
    );
    return;
  }
  if (type == 'flutter.material.CircleAvatar') {
    _expect(
      !properties.containsKey('radius') ||
          (!properties.containsKey('minRadius') &&
              !properties.containsKey('maxRadius')),
      'Canvas CircleAvatar radius excludes minRadius and maxRadius: '
      '$path/properties/radius',
    );
    double? radius(String name) {
      final value = properties[name]?.value;
      return value is CanvasEnumValue
          ? double.infinity
          : (value as num?)?.toDouble();
    }

    _expect(
      2 * (radius('radius') ?? radius('minRadius') ?? 0) <=
          2 * (radius('radius') ?? radius('maxRadius') ?? double.infinity),
      'Canvas CircleAvatar minimum diameter cannot exceed maximum diameter: '
      '$path/properties/minRadius',
    );
    for (final pair in const {
      'backgroundImage': 'onBackgroundImageError',
      'foregroundImage': 'onForegroundImageError',
    }.entries) {
      final provider = properties[pair.key]?.value;
      _expect(
        !properties.containsKey(pair.value) ||
            provider is CanvasImageProviderValue,
        'Canvas CircleAvatar ${pair.value} requires ${pair.key}: '
        '$path/properties/${pair.value}',
      );
      if (provider is CanvasImageProviderValue &&
          provider.resolution is CanvasResolvedImageValue) {
        budget.imageResourceIds.add(
          (provider.resolution as CanvasResolvedImageValue).resourceId,
        );
      }
    }
    return;
  }
  if (type == 'flutter.widgets.SliverVisibility') {
    for (final dependency in const {
      'maintainAnimation': 'maintainState', 'maintainSize': 'maintainAnimation',
      'maintainSemantics': 'maintainSize', 'maintainInteractivity': 'maintainSize',
    }.entries) {
      _expect(properties[dependency.key]?.value != true || properties[dependency.value]?.value == true,
        'Canvas SliverVisibility ${dependency.key} requires ${dependency.value}: $path/properties/${dependency.key}');
    }
  }
  if (type == 'flutter.widgets.Visibility') {
    for (final dependency in const {
      'maintainAnimation': 'maintainState',
      'maintainSize': 'maintainAnimation',
      'maintainSemantics': 'maintainSize',
      'maintainInteractivity': 'maintainSize',
      'maintainFocusability': 'maintainState',
    }.entries) {
      _expect(
        properties[dependency.key]?.value != true ||
            properties[dependency.value]?.value == true,
        'Canvas Visibility ${dependency.key} requires ${dependency.value}: '
        '$path/properties/${dependency.key}',
      );
    }
  }
  if (type == 'flutter.widgets.ClipPath') {
    _expect(
      !(properties.containsKey('clipper') && properties.containsKey('shape')),
      'Canvas ClipPath clipper and shape are mutually exclusive: '
      '$path/properties',
    );
  }
  if (type == 'flutter.widgets.Column' || type == 'flutter.widgets.Row') {
    final crossAxisAlignment = properties['crossAxisAlignment']?.value;
    if (crossAxisAlignment is CanvasEnumValue &&
        crossAxisAlignment.value == 'baseline') {
      _expect(
        properties.containsKey('textBaseline'),
        'Canvas $type requires textBaseline when crossAxisAlignment is baseline: '
        '$path/properties/textBaseline',
      );
    }
  }

  if (type == 'flutter.widgets.OverflowBox') {
    final minWidth = properties['minWidth']?.value as double?;
    final maxWidth = properties['maxWidth']?.value as double?;
    final minHeight = properties['minHeight']?.value as double?;
    final maxHeight = properties['maxHeight']?.value as double?;
    _expect(
      minWidth == null || maxWidth == null || minWidth <= maxWidth,
      'Canvas OverflowBox minWidth cannot exceed maxWidth: '
      '$path/properties/minWidth',
    );
    _expect(
      minHeight == null || maxHeight == null || minHeight <= maxHeight,
      'Canvas OverflowBox minHeight cannot exceed maxHeight: '
      '$path/properties/minHeight',
    );
  }

  if (type == 'flutter.material.Badge') {
    _expect(
      !properties.containsKey('maxCount') || properties.containsKey('count'),
      'Canvas Badge maxCount requires count: $path/properties/maxCount',
    );
    _validateAppBarTextStyleRelationships(
      properties,
      prefix: 'textStyle',
      path: path,
      widgetName: 'Badge',
    );
    return;
  }

  if (type == 'flutter.material.FloatingActionButton') {
    final variant = properties['variant']?.value;
    _expect(
      variant == 'standard' || !properties.containsKey('mini'),
      'Canvas FloatingActionButton mini requires standard variant: $path/properties/mini',
    );
    _expect(
      variant == 'standard' ||
          variant == 'extended' ||
          !properties.containsKey('isExtended'),
      'Canvas FloatingActionButton isExtended is unavailable for small/large: $path/properties/isExtended',
    );
    for (final name in properties.keys.where(
      (name) => name.startsWith('extended'),
    )) {
      _expect(
        variant == 'extended',
        'Canvas FloatingActionButton $name requires extended variant: $path/properties/$name',
      );
    }
    _validateCardRelationships(
      properties,
      path,
      widgetName: 'FloatingActionButton',
    );
    _validateAppBarTextStyleRelationships(
      properties,
      prefix: 'extendedTextStyle',
      path: path,
      widgetName: 'FloatingActionButton',
    );
    return;
  }
  if (type == 'flutter.material.Card') {
    _validateCardRelationships(properties, path);
    return;
  }

  if (type == 'flutter.material.FlexibleSpaceBarSettings') {
    final min = properties['minExtent']!.value as num;
    final max = properties['maxExtent']!.value as num;
    final current = properties['currentExtent']!.value as num;
    _expect(min <= max, 'Canvas FlexibleSpaceBarSettings Min extent must not exceed Max extent: $path/properties/minExtent');
    _expect(current >= min && current <= max,
      'Canvas FlexibleSpaceBarSettings Current extent must be within Min extent..Max extent: $path/properties/currentExtent');
    return;
  }
  if (isCanvasSliverAppBarType(type)) {
    _expect(properties['snap']?.value != true || properties['floating']?.value == true,
      'Canvas SliverAppBar snap requires floating: $path/properties/snap');
    final toolbar = properties['toolbarHeight']?.value as num? ?? (type == 'flutter.material.SliverAppBar' ? 56 : 64);
    final collapsed = properties['collapsedHeight']?.value as num?;
    _expect(collapsed == null || collapsed >= toolbar, 'Canvas SliverAppBar collapsedHeight must be at least toolbarHeight: $path/properties/collapsedHeight');
    for (final whole in _sliverAppBarWholeTypes.keys) {
      _expect(!properties.containsKey(whole) || !properties.keys.any((n) => n != whole && n.startsWith(whole)),
        'Canvas SliverAppBar whole $whole and local fields are mutually exclusive: $path/properties/$whole');
    }
    _validateAppBarRelationships(properties, path);
    return;
  }
  if (type == 'flutter.material.AppBar') {
    _validateAppBarRelationships(properties, path);
    return;
  }

  if (type == 'flutter.material.ElevatedButton') {
    _validateElevatedButtonRelationships(properties, path);
    return;
  }
  if (type == 'flutter.material.SubmenuButton') {
    _expect(
      !properties.containsKey('submenuIcon') ||
          !properties.keys.any(
            (name) => name != 'submenuIcon' && name.startsWith('submenuIcon'),
          ),
      'Canvas SubmenuButton whole submenuIcon and local icon fields are mutually exclusive: $path/properties/submenuIcon',
    );
    final menuProperties = <String, CanvasValue>{
      for (final entry in properties.entries)
        if (entry.key.startsWith('menuStyle'))
          'style${entry.key.substring(9)}': entry.value,
    };
    _validatePropertyRelationships(
      'flutter.material.MenuAnchor',
      menuProperties,
      path,
      budget,
    );
  }
  if (type == 'flutter.material.MenuAnchor') {
    _expect(
      !properties.containsKey('style') ||
          !properties.keys.any(_isMenuStyleLocal),
      'Canvas MenuAnchor whole style and local style fields are mutually exclusive: $path/properties/style',
    );
    _validateElevatedButtonRelationships(
      properties,
      path,
      widgetName: 'MenuAnchor',
      statePrefixes: _textButtonStatePrefixes,
    );
    _validateTextButtonEffectiveStyles(properties, path, 'MenuAnchor');
    return;
  }
  if (type == 'flutter.material.MenuBar') {
    _expect(
      !properties.containsKey('style') ||
          !properties.keys.any(_isMenuStyleLocal),
      'Canvas MenuBar whole style and local style fields are mutually exclusive: $path/properties/style',
    );
    return;
  }
  if (type == 'flutter.material.MenuItemButton') {
    final locals = properties.keys
        .where((name) => name.startsWith('shortcut') && name != 'shortcut')
        .toList();
    _expect(
      !properties.containsKey('shortcut') || locals.isEmpty,
      'Canvas MenuItemButton shortcut reference and local fields are mutually exclusive: $path/properties',
    );
    if (locals.isNotEmpty) {
      final trigger = properties.containsKey('shortcutTrigger');
      final character = properties.containsKey('shortcutCharacter');
      _expect(
        trigger != character,
        'Canvas MenuItemButton local shortcut requires exactly one trigger or character: $path/properties',
      );
      _expect(
        !character ||
            (!properties.containsKey('shortcutShift') &&
                !properties.containsKey('shortcutNumLock')),
        'Canvas MenuItemButton character shortcut forbids Shift and NumLock fields: $path/properties',
      );
    }
  }
  if (type == 'flutter.material.TextButton' ||
      type == 'flutter.material.OutlinedButton' ||
      type == 'flutter.material.FilledButton' ||
      type == 'flutter.material.MenuItemButton' ||
      type == 'flutter.material.SubmenuButton' ||
      type == 'flutter.material.IconButton') {
    final widgetName = type.split('.').last;
    final icon = {'icon', 'tonalIcon'}.contains(properties['variant']?.value);
    _expect(
      icon || !properties.containsKey('iconAlignment'),
      'Canvas $widgetName iconAlignment requires the icon variant: $path/properties/iconAlignment',
    );
    _expect(
      !icon || !properties.containsKey('isSemanticButton'),
      'Canvas $widgetName.icon does not accept isSemanticButton: $path/properties/isSemanticButton',
    );
    _expect(
      !properties.containsKey('style') ||
          !properties.keys.any(
            (name) => name != 'style' && name.startsWith('style'),
          ),
      'Canvas $widgetName style reference and local style fields are mutually exclusive: $path/properties/style',
    );
    _validateElevatedButtonRelationships(
      properties,
      path,
      widgetName: widgetName,
      statePrefixes: _textButtonStatePrefixes,
    );
    _validateTextButtonEffectiveStyles(properties, path, widgetName);
    return;
  }

  if (type == 'flutter.widgets.RelativePositionedTransition' && properties['rect']?.kind == 'string') {
    final nullValue = properties['rect']!.value == 'null';
    final localSize = properties['size']?.kind == 'string';
    for (final axis in [['rectLeft', 'rectWidth', 'sizeWidth'], ['rectTop', 'rectHeight', 'sizeHeight']]) {
      final origin = nullValue ? 0.0 : (properties[axis[0]]!.value as num).toDouble();
      final extent = nullValue ? 0.0 : (properties[axis[1]]!.value as num).toDouble();
      final size = localSize ? (properties[axis[2]]!.value as num).toDouble() : null;
      _expect((origin + extent).isFinite && ((origin + extent) - origin).isFinite
          && (size == null || (size - (origin + extent)).isFinite),
          'Canvas local Rect edges and reference Size offsets must remain finite: $path/properties');
    }
  }
  if (type == 'flutter.widgets.AnimatedPositioned.fromRect' &&
      properties['rect']?.kind != 'dartObjectReferencePresence') {
    for (final pair in [['rectLeft', 'rectWidth'], ['rectTop', 'rectHeight']]) {
      final origin = (properties[pair[0]]!.value as num).toDouble();
      final extent = (properties[pair[1]]!.value as num).toDouble();
      _expect((origin + extent).isFinite && ((origin + extent) - origin).isFinite,
          'Canvas local Rect edges and derived sizes must remain finite: $path/properties/${pair[0]}');
    }
  }
  if (isCanvasStackPositionedWidgetType(type) && !type.endsWith('.fromRect')) {
    bool present(String name) => properties[name] != null && properties[name]!.kind != 'null';
    for (final axis in [type.endsWith('Directional') ? ['start','end','width'] : ['left','right','width'], ['top','bottom','height']]) {
      _expect(!axis.every(present), 'Canvas $type allows at most two non-null fields per axis: ${axis.join(', ')} at $path/properties');
    }
  }
  if (type == 'flutter.widgets.AnimatedContainer') {
    bool present(String name) => properties[name] != null && properties[name]!.kind != 'null';
    _expect(!(present('color') && present('decoration')),
      'Canvas AnimatedContainer color and decoration are mutually exclusive: $path/properties');
    final clip = properties['clipBehavior']?.value;
    _expect(clip is! CanvasEnumValue || clip.value == 'none' || present('color') || present('decoration'),
      'Canvas AnimatedContainer non-none clipBehavior requires background color or decoration: $path/properties/clipBehavior');
    for (final name in const ['decoration', 'foregroundDecoration']) {
      _recordBoxDecorationImageResource(properties[name]?.value, budget);
    }
    return;
  }

  if (type == 'flutter.widgets.Container') {
    _expect(
      !(properties.containsKey('color') &&
          properties.containsKey('decoration')),
      'Canvas Container color and decoration are mutually exclusive: '
      '$path/properties',
    );
    final clip = properties['clipBehavior']?.value;
    _expect(
      clip is! CanvasEnumValue ||
          clip.value == 'none' ||
          properties.containsKey('decoration'),
      'Canvas Container non-none clipBehavior requires decoration: '
      '$path/properties/clipBehavior',
    );
    for (final name in const ['decoration', 'foregroundDecoration']) {
      _recordBoxDecorationImageResource(properties[name]?.value, budget);
    }
    return;
  }

  if (type == 'flutter.widgets.DecoratedBox' || type == 'flutter.widgets.DecoratedBoxTransition') {
    _recordBoxDecorationImageResource(properties['decoration']?.value, budget);
    return;
  }

  if (type == 'flutter.widgets.FadeInImage') {
    for (final name in const ['placeholder','image']) {
      final provider = properties[name]!.value;
      if (provider is CanvasImageProviderValue && provider.resolution is CanvasResolvedImageValue) {
        budget.imageResourceIds.add((provider.resolution as CanvasResolvedImageValue).resourceId);
      }
    }
    return;
  }
  if (type == 'flutter.widgets.ImageIcon') {
    final provider = properties['image']!.value;
    if (provider is CanvasImageProviderValue &&
        provider.resolution is CanvasResolvedImageValue) {
      budget.imageResourceIds.add(
        (provider.resolution as CanvasResolvedImageValue).resourceId,
      );
    }
    return;
  }

  if (type == 'flutter.widgets.Image') {
    final provider = properties['image']?.value;
    _expect(
      provider is CanvasImageProviderValue,
      'Canvas Image requires a direct image provider: $path/properties/image',
    );
    final resolution = (provider! as CanvasImageProviderValue).resolution;
    if (resolution is CanvasResolvedImageValue) {
      budget.imageResourceIds.add(resolution.resourceId);
    }

    const sliceNames = [
      'centerSliceLeft',
      'centerSliceTop',
      'centerSliceRight',
      'centerSliceBottom',
    ];
    final presentSlices = sliceNames
        .where(properties.containsKey)
        .toList(growable: false);
    _expect(
      presentSlices.isEmpty || presentSlices.length == sliceNames.length,
      'Canvas Image centerSlice coordinates must be all present or all '
      'omitted: $path/properties',
    );
    if (presentSlices.isNotEmpty) {
      final left = properties['centerSliceLeft']!.value as double;
      final top = properties['centerSliceTop']!.value as double;
      final right = properties['centerSliceRight']!.value as double;
      final bottom = properties['centerSliceBottom']!.value as double;
      _expect(
        left < right && top < bottom,
        'Canvas Image centerSlice must have positive width and height: '
        '$path/properties',
      );
      final fit = properties['fit']?.value;
      _expect(
        fit is! CanvasEnumValue ||
            (fit.value != 'cover' && fit.value != 'none'),
        'Canvas Image centerSlice rejects cover and none fits: '
        '$path/properties/fit',
      );
    }
    return;
  }

  if (type == 'flutter.material.TextField') {
    const radiusNames = ['cursorRadiusX', 'cursorRadiusY'];
    final presentRadii = radiusNames
        .where(properties.containsKey)
        .toList(growable: false);
    _expect(
      presentRadii.isEmpty || presentRadii.length == radiusNames.length,
      'Canvas TextField cursorRadius coordinates must be all present or all '
      'omitted: $path/properties',
    );

    const paddingNames = [
      'scrollPaddingLeft',
      'scrollPaddingTop',
      'scrollPaddingRight',
      'scrollPaddingBottom',
    ];
    final presentPadding = paddingNames
        .where(properties.containsKey)
        .toList(growable: false);
    _expect(
      presentPadding.isEmpty || presentPadding.length == paddingNames.length,
      'Canvas TextField scrollPadding coordinates must be all present or all '
      'omitted: $path/properties',
    );

    final expands = properties['expands']?.value == true;
    _expect(
      !expands ||
          (!properties.containsKey('maxLines') &&
              !properties.containsKey('minLines')),
      'Canvas TextField expands rejects explicit minLines and maxLines: '
      '$path/properties',
    );
    final maxLines = properties['maxLines']?.value as int? ?? 1;
    final minLines = properties['minLines']?.value as int?;
    _expect(
      minLines == null || minLines <= maxLines,
      'Canvas TextField minLines cannot exceed the effective maxLines: '
      '$path/properties/minLines',
    );
    final obscureText = properties['obscureText']?.value == true;
    _expect(
      !obscureText || (!expands && maxLines == 1),
      'Canvas TextField obscureText requires a non-expanding single line: '
      '$path/properties/obscureText',
    );
    final maxLength = properties['maxLength']?.value as int?;
    _expect(
      maxLength == null || maxLength == -1 || maxLength > 0,
      'Canvas TextField maxLength must be -1 or positive: '
      '$path/properties/maxLength',
    );
    final inputAction = properties['textInputAction']?.value;
    final effectiveMultiline = expands || maxLines != 1;
    _expect(
      inputAction is! CanvasEnumValue ||
          inputAction.value != 'newline' ||
          !effectiveMultiline ||
          properties['keyboardType']?.value != 'text',
      'Canvas TextField multiline newline action rejects the explicit text '
      'keyboard type: $path/properties/keyboardType',
    );
    return;
  }

  if (type == 'flutter.widgets.AnimatedDefaultTextStyle' || type == 'flutter.widgets.DefaultTextStyle' || type == 'flutter.widgets.DefaultTextStyle.merge' || type == 'flutter.widgets.DefaultTextStyleTransition') {
    _expect(!(properties['style']?.kind != 'string' &&
        properties.keys.any((name) => name.startsWith('style') && name != 'style')),
        'Canvas $type whole style/reference/null/omission and local fields are mutually exclusive: $path/properties/style');
    _expect(!(properties.containsKey('textHeightBehavior') &&
        properties.keys.any((name) => name.startsWith('textHeight') && name != 'textHeightBehavior')),
        'Canvas $type whole height behavior/null and local fields are mutually exclusive: $path/properties/textHeightBehavior');
  }
  if (type != 'flutter.widgets.Text' && type != 'flutter.widgets.AnimatedDefaultTextStyle' &&
      type != 'flutter.widgets.DefaultTextStyle' && type != 'flutter.widgets.DefaultTextStyle.merge' && type != 'flutter.widgets.DefaultTextStyleTransition') {
    return;
  }

  _validateLocaleSubtag(
    properties,
    'localeLanguageCode',
    RegExp(r'^(?:[a-z]{2,3}|[a-z]{5,8})$'),
    path,
  );
  _validateLocaleSubtag(
    properties,
    'localeScriptCode',
    RegExp(r'^[A-Z][a-z]{3}$'),
    path,
  );
  _validateLocaleSubtag(
    properties,
    'localeCountryCode',
    RegExp(r'^(?:[A-Z]{2}|[0-9]{3})$'),
    path,
  );
  _validateLocaleSubtag(
    properties,
    'styleLocaleLanguageCode',
    RegExp(r'^(?:[a-z]{2,3}|[a-z]{5,8})$'),
    path,
  );
  _validateLocaleSubtag(
    properties,
    'styleLocaleScriptCode',
    RegExp(r'^[A-Z][a-z]{3}$'),
    path,
  );
  _validateLocaleSubtag(
    properties,
    'styleLocaleCountryCode',
    RegExp(r'^(?:[A-Z]{2}|[0-9]{3})$'),
    path,
  );

  _validateFontPackageRelationship(
    properties,
    packageName: 'stylePackage',
    fontFamilyName: 'styleFontFamily',
    fallbackName: 'styleFontFamilyFallback',
    path: path,
  );
  _expect(
    !(properties.containsKey('styleColor') &&
        properties.containsKey('styleForeground')),
    'Canvas Text styleColor and styleForeground are mutually exclusive: '
    '$path/properties/styleForeground',
  );
  _expect(
    !(properties.containsKey('styleBackgroundColor') &&
        properties.containsKey('styleBackground')),
    'Canvas Text styleBackgroundColor and styleBackground are mutually exclusive: '
    '$path/properties/styleBackground',
  );
  _validateFontPackageRelationship(
    properties,
    packageName: 'strutPackage',
    fontFamilyName: 'strutFontFamily',
    fallbackName: 'strutFontFamilyFallback',
    path: path,
  );

  final semanticsIdentifier = properties['semanticsIdentifier']?.value;
  if (semanticsIdentifier is! String) {
    return;
  }
  final propertyPath = '$path/properties/semanticsIdentifier';
  final firstPath = budget.semanticsIdentifierPaths[semanticsIdentifier];
  _expect(
    firstPath == null,
    'Canvas Text semanticsIdentifier must be unique: $propertyPath duplicates '
    '$firstPath',
  );
  budget.semanticsIdentifierPaths[semanticsIdentifier] = propertyPath;
}

void _recordBoxDecorationImageResource(Object? value, _NodeBudget budget) {
  if (value is! CanvasBoxDecorationValue) {
    return;
  }
  final resolution = value.image?.image.resolution;
  if (resolution is CanvasResolvedImageValue) {
    budget.imageResourceIds.add(resolution.resourceId);
  }
}

void _validateElevatedButtonRelationships(
  Map<String, CanvasValue> properties,
  String path, {
  String widgetName = 'ElevatedButton',
  List<String> statePrefixes = const [
    'style',
    'styleDisabled',
    'stylePressed',
    'styleHovered',
    'styleFocused',
  ],
}) {
  for (final prefix in statePrefixes) {
    for (final dimension in const ['Width', 'Height']) {
      final minimumName = '${prefix}Minimum$dimension';
      final fixedName = '${prefix}Fixed$dimension';
      final maximumName = '${prefix}Maximum$dimension';
      final minimum = properties[minimumName]?.value as num?;
      final fixed = properties[fixedName]?.value as num?;
      final maximum = properties[maximumName]?.value as num?;
      _expect(
        minimum == null || maximum == null || minimum <= maximum,
        'Canvas $widgetName $minimumName must be less than or equal to '
        '$maximumName: $path/properties/$maximumName',
      );
      _expect(
        widgetName != 'ElevatedButton' ||
            fixed == null ||
            minimum == null ||
            fixed >= minimum,
        'Canvas $widgetName $fixedName must be greater than or equal to '
        '$minimumName: $path/properties/$fixedName',
      );
      _expect(
        widgetName != 'ElevatedButton' ||
            fixed == null ||
            maximum == null ||
            fixed <= maximum,
        'Canvas $widgetName $fixedName must be less than or equal to '
        '$maximumName: $path/properties/$fixedName',
      );
    }

    final radiusFields = {
      '${prefix}ShapeRadiusTopLeft',
      '${prefix}ShapeRadiusTopRight',
      '${prefix}ShapeRadiusBottomRight',
      '${prefix}ShapeRadiusBottomLeft',
    };
    final eccentricity = '${prefix}ShapeCircleEccentricity';
    final kindName = '${prefix}ShapeKind';
    final localKind = properties[kindName]?.value;
    final kind =
        localKind ??
        (prefix != 'style' && prefix != 'styleDisabled'
            ? properties['styleShapeKind']?.value
            : null);
    final hasShapeLeaf = <String>{
      ...radiusFields,
      eccentricity,
    }.any(properties.containsKey);
    _expect(
      kind is String || !hasShapeLeaf,
      'Canvas $widgetName shape fields require an effective local '
      '$kindName: $path/properties/$kindName',
    );
    if (kind is String) {
      final supportsRadius = const {
        'roundedRectangle',
        'roundedSuperellipse',
        'beveledRectangle',
        'continuousRectangle',
      }.contains(kind);
      _expect(
        supportsRadius || !radiusFields.any(properties.containsKey),
        'Canvas $widgetName $kind shape does not accept corner radii: '
        '$path/properties/$kindName',
      );
      _expect(
        kind == 'circle' || !properties.containsKey(eccentricity),
        'Canvas $widgetName $kind shape does not accept circle '
        'eccentricity: $path/properties/$eccentricity',
      );
    }

    final textPrefix = '${prefix}Text';
    _validateLocaleSubtag(
      properties,
      '${textPrefix}LocaleLanguageCode',
      RegExp(r'^(?:[a-z]{2,3}|[a-z]{5,8})$'),
      path,
    );
    _validateLocaleSubtag(
      properties,
      '${textPrefix}LocaleScriptCode',
      RegExp(r'^[A-Z][a-z]{3}$'),
      path,
    );
    _validateLocaleSubtag(
      properties,
      '${textPrefix}LocaleCountryCode',
      RegExp(r'^(?:[A-Z]{2}|[0-9]{3})$'),
      path,
    );
    _validateElevatedButtonFontPackageRelationship(
      properties,
      prefix,
      path,
      additionalStates: widgetName != 'ElevatedButton',
      widgetName: widgetName,
    );
    _expect(
      !(properties.containsKey('${textPrefix}BackgroundColor') &&
          properties.containsKey('${textPrefix}Background')),
      'Canvas $widgetName ${textPrefix}BackgroundColor and '
      '${textPrefix}Background are mutually exclusive: '
      '$path/properties/${textPrefix}Background',
    );
  }

  final textStatePrefixes = statePrefixes;
  final hasLocalTextInheritance = textStatePrefixes.any(
    (prefix) =>
        properties.containsKey('${prefix}TextInherit') ||
        properties.containsKey('${prefix}TextTheme'),
  );
  if (hasLocalTextInheritance) {
    final base = properties['styleTextInherit']?.value;
    final disabled = properties['styleDisabledTextInherit']?.value;
    _expect(
      base is bool,
      'Canvas $widgetName local TextStyle inheritance requires '
      'styleTextInherit: $path/properties/styleTextInherit',
    );
    _expect(
      disabled is bool && disabled == base,
      'Canvas $widgetName disabled TextStyle inherit must equal the base: '
      '$path/properties/styleDisabledTextInherit',
    );
    for (final prefix in textStatePrefixes) {
      final inheritName = '${prefix}TextInherit';
      final themeName = '${prefix}TextTheme';
      final inherit = properties[inheritName]?.value;
      _expect(
        inherit == null || inherit == base,
        'Canvas $widgetName $inheritName must equal styleTextInherit: '
        '$path/properties/$inheritName',
      );
      _expect(
        !properties.containsKey(themeName) || inherit == base,
        'Canvas $widgetName $themeName requires an explicit matching '
        '$inheritName: $path/properties/$inheritName',
      );
    }
  }

  const alignmentNames = {
    'styleAlignmentKind',
    'styleAlignmentX',
    'styleAlignmentY',
  };
  final alignmentCount = alignmentNames.where(properties.containsKey).length;
  _expect(
    alignmentCount == 0 || alignmentCount == alignmentNames.length,
    'Canvas $widgetName alignment requires styleAlignmentKind, '
    'styleAlignmentX, and styleAlignmentY together: '
    '$path/properties/styleAlignmentKind',
  );
}

void _validateTextButtonEffectiveStyles(
  Map<String, CanvasValue> properties,
  String path,
  String widgetName,
) {
  const priority = [
    'styleError',
    'styleDragged',
    'stylePressed',
    'styleSelected',
    'styleScrolledUnder',
    'styleHovered',
    'styleFocused',
  ];
  for (var mask = -1; mask < (1 << priority.length); mask++) {
    final prefixes = mask < 0
        ? const ['styleDisabled']
        : [
            for (var i = 0; i < priority.length; i++)
              if ((mask & (1 << i)) != 0) priority[i],
            'style',
          ];
    String? effectiveName(String suffix) {
      for (final prefix in prefixes) {
        if (properties.containsKey('$prefix$suffix')) return '$prefix$suffix';
      }
      return null;
    }

    Object? effective(String suffix) =>
        properties[effectiveName(suffix)]?.value;
    for (final dimension in ['Width', 'Height']) {
      final minimum = effective('Minimum$dimension') as num?;
      final maximum = effective('Maximum$dimension') as num?;
      _expect(
        minimum == null || maximum == null || minimum <= maximum,
        'Canvas $widgetName effective minimum exceeds explicit local maximum: $path/properties/${effectiveName('Maximum$dimension')}',
      );
    }
    final kind = effective('ShapeKind');
    for (final suffix in [
      'ShapeRadiusTopLeft',
      'ShapeRadiusTopRight',
      'ShapeRadiusBottomLeft',
      'ShapeRadiusBottomRight',
    ]) {
      final radius = effectiveName(suffix);
      _expect(
        radius == null ||
            const {
              'roundedRectangle',
              'roundedSuperellipse',
              'beveledRectangle',
              'continuousRectangle',
            }.contains(kind),
        'Canvas $widgetName effective corner radius requires a compatible local shape kind: $path/properties/$radius',
      );
    }
    final eccentricity = effectiveName('ShapeCircleEccentricity');
    _expect(
      eccentricity == null || kind == 'circle',
      'Canvas $widgetName effective eccentricity requires circle shape: $path/properties/$eccentricity',
    );
  }
}

void _validateCardRelationships(
  Map<String, CanvasValue> properties,
  String path, {
  String widgetName = 'Card',
  String prefix = 'shape',
}) {
  String field(String suffix) => '$prefix$suffix';
  final builtInFields = properties.keys
      .where((name) => name.startsWith(prefix) && name != prefix)
      .toSet();
  _expect(
    !properties.containsKey(prefix) || builtInFields.isEmpty,
    'Canvas $widgetName $prefix reference and built-in shape fields are mutually exclusive: $path/properties/$prefix',
  );
  final kind = properties[field('Kind')]?.value;
  _expect(
    kind is String || builtInFields.isEmpty,
    'Canvas $widgetName shape details require ${field('Kind')}: $path/properties/${field('Kind')}',
  );
  final allowed = <String>{
    field('Kind'),
    field('SideColor'),
    field('SideWidth'),
    field('SideStyle'),
    field('SideStrokeAlign'),
  };
  if (const {
    'roundedRectangle',
    'beveledRectangle',
    'continuousRectangle',
    'roundedSuperellipse',
  }.contains(kind)) {
    allowed.add(field('Radius'));
  }
  if (kind == 'circle' || kind == 'oval') {
    allowed.add(field('CircleEccentricity'));
  }
  if (kind == 'star' || kind == 'polygon') {
    allowed.addAll({
      field('Points'),
      field('PointRounding'),
      field('Rotation'),
      field('Squash'),
    });
  }
  if (kind == 'star') {
    allowed.addAll({field('InnerRadiusRatio'), field('ValleyRounding')});
  }
  if (kind == 'linear') {
    for (final edge in ['Start', 'End', 'Top', 'Bottom']) {
      allowed.addAll({field('${edge}Size'), field('${edge}Alignment')});
    }
  }
  for (final field in builtInFields) {
    _expect(
      allowed.contains(field),
      'Canvas $widgetName $kind shape does not accept $field: $path/properties/$field',
    );
  }
  final point = properties[field('PointRounding')]?.value as num? ?? 0;
  final valley = properties[field('ValleyRounding')]?.value as num? ?? 0;
  _expect(
    point + valley <= 1,
    'Canvas $widgetName star point and valley rounding sum must not exceed one: $path/properties/${field('PointRounding')}',
  );
}

void _validateAppBarRelationships(
  Map<String, CanvasValue> properties,
  String path,
) {
  const sideFields = {
    'shapeSideColor',
    'shapeSideWidth',
    'shapeSideStyle',
    'shapeSideStrokeAlign',
  };
  const radiusFields = {
    'shapeRadiusTopLeft',
    'shapeRadiusTopRight',
    'shapeRadiusBottomRight',
    'shapeRadiusBottomLeft',
  };
  const eccentricity = 'shapeCircleEccentricity';
  final kind = properties['shapeKind']?.value;
  final hasShapeLeaf = <String>{
    ...sideFields,
    ...radiusFields,
    eccentricity,
  }.any(properties.containsKey);
  _expect(
    kind is String || !hasShapeLeaf,
    'Canvas AppBar shape fields require shapeKind: '
    '$path/properties/shapeKind',
  );
  if (kind is String) {
    final supportsRadius = const {
      'roundedRectangle',
      'beveledRectangle',
      'continuousRectangle',
    }.contains(kind);
    final hasRadius = radiusFields.any(properties.containsKey);
    _expect(
      supportsRadius || !hasRadius,
      'Canvas AppBar $kind shape does not accept corner radii: '
      '$path/properties/shapeKind',
    );
    _expect(
      kind == 'circle' || !properties.containsKey(eccentricity),
      'Canvas AppBar $kind shape does not accept circle eccentricity: '
      '$path/properties/$eccentricity',
    );
  }
  _validateAppBarTextStyleRelationships(
    properties,
    prefix: 'toolbarTextStyle',
    path: path,
  );
  _validateAppBarTextStyleRelationships(
    properties,
    prefix: 'titleTextStyle',
    path: path,
  );
}

void _validateAppBarTextStyleRelationships(
  Map<String, CanvasValue> properties, {
  required String prefix,
  required String path,
  String widgetName = 'AppBar',
}) {
  _validateLocaleSubtag(
    properties,
    '${prefix}LocaleLanguageCode',
    RegExp(r'^(?:[a-z]{2,3}|[a-z]{5,8})$'),
    path,
  );
  _validateLocaleSubtag(
    properties,
    '${prefix}LocaleScriptCode',
    RegExp(r'^[A-Z][a-z]{3}$'),
    path,
  );
  _validateLocaleSubtag(
    properties,
    '${prefix}LocaleCountryCode',
    RegExp(r'^(?:[A-Z]{2}|[0-9]{3})$'),
    path,
  );
  _validateFontPackageRelationship(
    properties,
    packageName: '${prefix}Package',
    fontFamilyName: '${prefix}FontFamily',
    fallbackName: '${prefix}FontFamilyFallback',
    path: path,
  );
  _expect(
    !(properties.containsKey('${prefix}Color') &&
        properties.containsKey('${prefix}Foreground')),
    'Canvas $widgetName ${prefix}Color and ${prefix}Foreground are mutually '
    'exclusive: $path/properties/${prefix}Foreground',
  );
  _expect(
    !(properties.containsKey('${prefix}BackgroundColor') &&
        properties.containsKey('${prefix}Background')),
    'Canvas $widgetName ${prefix}BackgroundColor and ${prefix}Background are '
    'mutually exclusive: $path/properties/${prefix}Background',
  );
}

void _validateLocaleSubtag(
  Map<String, CanvasValue> properties,
  String name,
  RegExp pattern,
  String path,
) {
  final value = properties[name]?.value;
  if (value == null) {
    return;
  }
  _expect(
    value is String && pattern.hasMatch(value),
    'Canvas Text locale subtag is invalid: $path/properties/$name',
  );
}

void _validateFontPackageRelationship(
  Map<String, CanvasValue> properties, {
  required String packageName,
  required String fontFamilyName,
  required String fallbackName,
  required String path,
}) {
  final package = properties[packageName]?.value;
  if (package == null) {
    return;
  }
  _expect(
    package is String && package.trim().isNotEmpty,
    'Canvas Text font package must be non-empty: '
    '$path/properties/$packageName',
  );
  _expect(
    _hasNonEmptyString(properties, fontFamilyName) ||
        _hasNonEmptyLine(properties, fallbackName),
    'Canvas Text $packageName requires $fontFamilyName or $fallbackName: '
    '$path/properties/$packageName',
  );
}

void _validateElevatedButtonFontPackageRelationship(
  Map<String, CanvasValue> properties,
  String prefix,
  String path, {
  bool additionalStates = false,
  String widgetName = 'ElevatedButton',
}) {
  final textPrefix = '${prefix}Text';
  final packageName = '${textPrefix}Package';
  final package = properties[packageName]?.value;
  if (package == null) {
    return;
  }
  _expect(
    package is String && package.trim().isNotEmpty,
    'Canvas Text font package must be non-empty: '
    '$path/properties/$packageName',
  );

  final familyName = '${textPrefix}FontFamily';
  final fallbackName = '${textPrefix}FontFamilyFallback';
  final mayUseBase =
      (prefix == 'styleFocused' ||
          prefix == 'styleHovered' ||
          prefix == 'stylePressed' ||
          (additionalStates &&
              prefix != 'style' &&
              prefix != 'styleDisabled')) &&
      properties['${textPrefix}Inherit']?.value != false;
  final hasFamily =
      (additionalStates &&
          mayUseBase &&
          _hasNonEmptyString(properties, 'styleTextFontFamily')) ||
      (properties.containsKey(familyName)
          ? _hasNonEmptyString(properties, familyName)
          : mayUseBase &&
                _hasNonEmptyString(properties, 'styleTextFontFamily'));
  final hasFallback =
      (additionalStates &&
          mayUseBase &&
          _hasNonEmptyLine(properties, 'styleTextFontFamilyFallback')) ||
      (properties.containsKey(fallbackName)
          ? _hasNonEmptyLine(properties, fallbackName)
          : mayUseBase &&
                _hasNonEmptyLine(properties, 'styleTextFontFamilyFallback'));
  _expect(
    hasFamily || hasFallback,
    'Canvas $widgetName $packageName requires an effective local '
    '$familyName or $fallbackName without crossing disabled/inherit-false '
    'state isolation: $path/properties/$packageName',
  );
}

bool _hasNonEmptyString(Map<String, CanvasValue> properties, String name) {
  final value = properties[name]?.value;
  return value is String && value.trim().isNotEmpty;
}

bool _hasNonEmptyLine(Map<String, CanvasValue> properties, String name) {
  final value = properties[name]?.value;
  return value is String &&
      value.split(RegExp(r'\r\n?|\n')).any((line) => line.trim().isNotEmpty);
}

Map<String, Object?> _object(Object? value, String path) {
  _expect(
    value is Map<String, Object?>,
    'Canvas value must be an object: $path',
  );
  return value! as Map<String, Object?>;
}

void _exactKeys(
  Map<String, Object?> object,
  String path,
  Set<String> expected,
) {
  _expect(
    object.length == expected.length &&
        object.keys.toSet().containsAll(expected),
    'Canvas object has missing or unknown fields: $path',
  );
}

void _allowedKeys(
  Map<String, Object?> object,
  String path,
  Set<String> allowed,
) {
  _expect(
    object.keys.every(allowed.contains),
    'Canvas object has unknown fields: $path',
  );
}

String _stableId(Object? value, String path) {
  final text = _boundedText(value, path, 36, 36);
  _expect(_stableIdPattern.hasMatch(text), 'Canvas identity is invalid: $path');
  return text;
}

int _sequence(Object? value, String path) {
  _expect(value is int, 'Canvas sequence must be an integer: $path');
  final sequence = value! as int;
  _expect(
    sequence >= 0 && sequence <= maxCanvasSequence,
    'Canvas sequence is outside the interoperable range: $path',
  );
  return sequence;
}

String _enumText(Object? value, String path, Set<String> allowed) {
  final text = _boundedText(value, path, 1, 32).toLowerCase();
  _expect(allowed.contains(text), 'Canvas enum value is not allowed: $path');
  return text;
}

String _exactEnumText(Object? value, String path, Set<String> allowed) {
  final text = _boundedText(value, path, 1, 32);
  _expect(allowed.contains(text), 'Canvas enum value is not allowed: $path');
  return text;
}

String _boundedText(Object? value, String path, int minimum, int maximum) {
  _expect(value is String, 'Canvas value must be a string: $path');
  final text = value! as String;
  _expect(
    text.runes.length >= minimum && text.runes.length <= maximum,
    'Canvas string length is outside its bounds: $path',
  );
  _expect(
    !text.runes.any(
      (codePoint) =>
          codePoint < 0x20 || (codePoint >= 0x7f && codePoint <= 0x9f),
    ),
    'Canvas string contains control characters: $path',
  );
  return text;
}

void _expectWellFormedUtf16(String value, String path) {
  final units = value.codeUnits;
  for (var index = 0; index < units.length; index++) {
    final unit = units[index];
    if (unit >= 0xd800 && unit <= 0xdbff) {
      _expect(
        index + 1 < units.length &&
            units[index + 1] >= 0xdc00 &&
            units[index + 1] <= 0xdfff,
        'Canvas string contains an unpaired surrogate: $path',
      );
      index++;
      continue;
    }
    _expect(
      unit < 0xdc00 || unit > 0xdfff,
      'Canvas string contains an unpaired surrogate: $path',
    );
  }
}

void _validateImageAssetName(String value, String path) {
  _expectWellFormedUtf16(value, path);
  final codeUnits = value.codeUnits;
  _expect(
    !value.runes.every(_isCanvasMetadataWhitespace) &&
        codeUnits.first > 0x20 &&
        codeUnits.last > 0x20,
    'Canvas image assetName must be non-blank without surrounding whitespace: $path',
  );
  _expect(
    !value.startsWith('/') && !value.startsWith('~') && !value.endsWith('/'),
    'Canvas image assetName must be a relative POSIX path: $path',
  );
  _expect(
    value
        .split('/')
        .every(
          (segment) => segment.isNotEmpty && segment != '.' && segment != '..',
        ),
    'Canvas image assetName contains an unsafe path segment: $path',
  );
  _expect(
    !value.runes.any(
      (codePoint) =>
          codePoint == 0x25 ||
          codePoint == 0x5c ||
          codePoint == 0x3a ||
          codePoint <= 0x1f ||
          (codePoint >= 0x7f && codePoint <= 0x9f) ||
          codePoint == 0x061c ||
          codePoint == 0x200e ||
          codePoint == 0x200f ||
          (codePoint >= 0x2028 && codePoint <= 0x202e) ||
          (codePoint >= 0x2066 && codePoint <= 0x2069) ||
          codePoint == 0xfeff,
    ),
    'Canvas image assetName contains an unsafe path character: $path',
  );
}

String _boundedPropertyText(
  Object? value,
  String path,
  int minimum,
  int maximum,
) {
  _expect(value is String, 'Canvas value must be a string: $path');
  final text = value! as String;
  _expect(
    text.runes.length >= minimum && text.runes.length <= maximum,
    'Canvas string length is outside its bounds: $path',
  );
  return text;
}

double _finiteNumber(
  Object? value,
  String path, {
  num? minimum,
  num? minimumExclusive,
  num? maximum,
}) {
  _expect(
    minimum == null || minimumExclusive == null,
    'Canvas number decoder has conflicting minimum bounds: $path',
  );
  _expect(value is num, 'Canvas value must be a number: $path');
  final number = (value! as num).toDouble();
  _expect(number.isFinite, 'Canvas number must be finite: $path');
  if (minimum != null) {
    _expect(number >= minimum, 'Canvas number is below its minimum: $path');
  }
  if (minimumExclusive != null) {
    _expect(
      number > minimumExclusive,
      'Canvas number is below its minimum: $path',
    );
  }
  if (maximum != null) {
    _expect(number <= maximum, 'Canvas number exceeds its maximum: $path');
  }
  return number;
}

Never _fail(String message) => throw FormatException(message);

void _expect(bool condition, String message) {
  if (!condition) {
    _fail(message);
  }
}
